function learnDigit(label,gl){
  EXS.push({label:label,asp:gl.asp,g:gl.g});
  try{var a=JSON.parse(localStorage.getItem("pasokhbarg.learn")||"[]");a.push([label,Math.round(gl.asp*1000)/1000,Array.from(gl.g).map(function(v){return Math.round(v*100)/100})]);
    localStorage.setItem("pasokhbarg.learn",JSON.stringify(a.slice(-150)))}catch(err){}
}
function readHeaders(G,rgba,W,H){
  var best=null;
  ["pink","color","badge"].forEach(function(profile){
    var items=[],sure=0;
    (profile==="badge"?findBadges(rgba,W,H):findBoxes(rgba,W,H,profile)).forEach(function(bx){
      var gl=boxGlyph(G,W,bx),key=0,d1=1e9,d2=1e9;
      if(gl){var cl=classify(gl,EXS);key=cl.label;d1=cl.d1;d2=cl.d2}
      if(gl&&d2/Math.max(d1,1e-6)>=1.4&&d1<40)sure++;
      if(gl)items.push({box:bx,key:key,d1:d1,d2:d2,gl:gl});   // a real answer box has a digit inside
    });
    if(profile==="badge"&&items.length>=2)best={items:items,sure:1e9,profile:profile};   // dark number badge plus answer box: the most specific layout
    else if(!best||sure>best.sure||(sure===best.sure&&items.length>best.items.length))best=(best&&best.profile==="badge")?best:{items:items,sure:sure,profile:profile};
  });
  return best.items;
}
function rotatedPixels(im,rot,maxW){
  var sw=(rot%2)?im.naturalHeight:im.naturalWidth,sh=(rot%2)?im.naturalWidth:im.naturalHeight,s=Math.min(1,maxW/Math.max(sw,sh));
  var W=Math.round(sw*s),H=Math.round(sh*s),c=document.createElement("canvas");c.width=W;c.height=H;
  var x=c.getContext("2d",{willReadFrequently:true});
  x.translate(W/2,H/2);x.rotate(rot*Math.PI/2);
  var dw=(rot%2)?H:W,dh=(rot%2)?W:H;
  x.drawImage(im,-dw/2,-dh/2,dw,dh);
  var rgba=x.getImageData(0,0,W,H).data,G=new Uint8Array(W*H);
  for(var i=0,j=0;i<G.length;i++,j+=4)G[i]=(rgba[j]*77+rgba[j+1]*150+rgba[j+2]*29)>>8;
  return {W:W,H:H,rgba:rgba,G:G,canvas:c};
}
function scoreItems(items){
  if(!items.length)return {n:0,q:1e9};
  var q=0;items.forEach(function(it){q+=Math.min(it.d1,80)});
  return {n:items.length,q:q/items.length};
}
function readExplanation(im,forcedRot){
  var rots=forcedRot!==undefined?[forcedRot]:[0,2,1,3],best=null;
  for(var r=0;r<rots.length;r++){
    var px=rotatedPixels(im,rots[r],2000),items=readHeaders(px.G,px.rgba,px.W,px.H),sc=scoreItems(items);
    var cand={rot:rots[r],px:px,items:items,sc:sc};
    // upright and upside-down differ only in how well the digits match; sideways pages have tall boxes and no match at all
    if(!best||sc.n>best.sc.n||(sc.n===best.sc.n&&sc.q<best.sc.q))best=cand;
    if(forcedRot===undefined&&r===1&&best.sc.n>0)break;
  }
  return best;
}
// columns from right to left (a spread has four), each from top to bottom
function orderBoxes(list){
  var arr=list.slice().sort(function(a,b){return b.box.x-a.box.x}),cols=[];
  arr.forEach(function(it){
    var col=cols[cols.length-1];
    if(col&&Math.abs(col.x-it.box.x)<3*it.box.w){col.items.push(it);col.x=(col.x*(col.items.length-1)+it.box.x)/col.items.length}
    else cols.push({x:it.box.x,items:[it]});
  });
  var out=[];
  cols.forEach(function(c){c.items.sort(function(a,b){return a.box.y-b.box.y});out=out.concat(c.items)});
  return out;
}

