function homography(dst,src){ // maps dst (u,v) -> src (x,y)
  var A=[],b=[];
  for(var i=0;i<4;i++){
    var u=dst[i][0],v=dst[i][1],x=src[i][0],y=src[i][1];
    A.push([u,v,1,0,0,0,-u*x,-v*x]);b.push(x);
    A.push([0,0,0,u,v,1,-u*y,-v*y]);b.push(y);
  }
  for(var c=0;c<8;c++){
    var m=c;for(var r=c+1;r<8;r++)if(Math.abs(A[r][c])>Math.abs(A[m][c]))m=r;
    var tA=A[c];A[c]=A[m];A[m]=tA;var tb=b[c];b[c]=b[m];b[m]=tb;
    for(var r2=c+1;r2<8;r2++){var f=A[r2][c]/A[c][c];for(var k=c;k<8;k++)A[r2][k]-=f*A[c][k];b[r2]-=f*b[c]}
  }
  var h=new Array(8);
  for(var r3=7;r3>=0;r3--){var s=b[r3];for(var k2=r3+1;k2<8;k2++)s-=A[r3][k2]*h[k2];h[r3]=s/A[r3][r3]}
  return h;
}
